#!/usr/bin/env node

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const root = resolve(process.argv[2] ?? process.cwd());
const launcher = resolve(root, "tools/mcp/launch.sh");
const configPath = resolve(root, ".codex/config.toml");

if (!existsSync(launcher)) {
  throw new Error(`MCP launcher not found: ${launcher}`);
}

const tomlString = value => JSON.stringify(value);
const config = [
  "# Generated by make mcp-setup. This machine-local file is ignored.",
  "",
  "[mcp_servers.chibi]",
  `command = ${tomlString("sh")}`,
  `args = [${tomlString(launcher)}]`,
  `cwd = ${tomlString(root)}`,
  "enabled = true",
  "startup_timeout_sec = 120",
  "tool_timeout_sec = 120",
  ""
].join("\n");

mkdirSync(resolve(root, ".codex"), { recursive: true });
writeFileSync(configPath, config, { mode: 0o600 });
console.log(`Wrote ${configPath}`);
